// project initialization
scene.setBackgroundImage(assets.image`sky`)
scroller.scrollBackgroundWithCamera(scroller.CameraScrollMode.OnlyHorizontal)
tiles.setCurrentTilemap(assets.tilemap`groundTilemap`)

let mySprite = sprites.create(assets.image`forwardNinja`, SpriteKind.Player)
tiles.placeOnTile(mySprite, tiles.getTileLocation(15, 7))
controller.moveSprite(mySprite)
scene.cameraFollowSprite(mySprite)
mySprite.ay = 500

controller.up.onEvent(ControllerButtonEvent.Pressed, function () {
    mySprite.ay = 0
    animation.runImageAnimation(mySprite, assets.animation`flyUpAnim`, 200, true)
})

controller.down.onEvent(ControllerButtonEvent.Pressed, function () {
    if (!mySprite.isHittingTile(CollisionDirection.Bottom)) {
        animation.runImageAnimation(mySprite, assets.animation`flyDownAnim`, 200, true)
        mySprite.ay = 500
    }
})

controller.left.onEvent(ControllerButtonEvent.Pressed, function () {
    if (mySprite.isHittingTile(CollisionDirection.Bottom)) {
        animation.runImageAnimation(mySprite, assets.animation`walkLeftAnim`, 200, true)
    } else {
        animation.runImageAnimation(mySprite, assets.animation`flyLeftAnim`, 200, true)
    }
})

controller.right.onEvent(ControllerButtonEvent.Pressed, function () {
    if (mySprite.isHittingTile(CollisionDirection.Bottom)) {
        animation.runImageAnimation(mySprite, assets.animation`walkRightAnim`, 200, true)
    } else {
        animation.runImageAnimation(mySprite, assets.animation`flyRightAnim`, 200, true)
    }
})

controller.anyButton.onEvent(ControllerButtonEvent.Released, function () {
    if (mySprite.isHittingTile(CollisionDirection.Bottom)) {
        animation.runImageAnimation(mySprite, assets.animation`idleAnim`, 500, true)
    }
})
